type PaperPollLane = "entry_watch" | "issuance_cycle" | "delivery_worker";
type PaperPollAcquireResult = { acquired: true; ownerToken: string; generation: number } | { acquired: false; activeOwnerToken: string | null; generation: number };
const PAPER_POLL_LEASE_MS: Record<PaperPollLane, number> = {
  entry_watch: 4 * 60_000,
  // Repair (2026-10-21): 5 minutes — strictly below the 15-minute entry
  // window (PAPER_ENTRY_WINDOW_MS). At 15 minutes a tick that died holding
  // the lease wedged the lane past the entry window (run 109); at 5 minutes
  // a crashed holder's lane recovers inside the window. Other lanes unchanged.
  issuance_cycle: 5 * 60_000,
  delivery_worker: 4 * 60_000,
};
const PAPER_POLL_MAX_PASSES = 2;

async function acquirePaperPollLease(ctx: Ctx, lane: PaperPollLane): Promise<PaperPollAcquireResult> {
  const db = ctx.db<typeof schema>();
  const now = new Date();
  // Fail fast on construction (2026-10-21): the acquire attempt's owner
  // token and TTL-derived lease expiry are built and validated BEFORE any
  // database write in this path — before the guard insert below and before
  // the acquire update. An empty owner token or an empty/invalid/past
  // expiry throws PaperPollLeaseConstructionError (kind
  // "lease_construction_invalid") and this attempt performs no write of any
  // kind, leaving the lane's lease row exactly as it was. This defect class
  // is input construction, not database contention; the 2026-10-21T19:00:21Z
  // issuance-cycle failure carried empty owner_token / lease_expires_at
  // parameters on this path's guard insert.
  const attempt = buildPaperPollLeaseAttempt({ lane, ownerToken: `${ctx.invocationId}:${lane}:${crypto.randomUUID()}`, ttlMs: PAPER_POLL_LEASE_MS[lane], now });
  // Guard/ensure-row insert: carries only placeholder nulls for owner and
  // expiry by construction, and onConflictDoNothing means it can never
  // mutate or wedge an existing lane row.
  await db.insert(schema.paperPollLeases).values({ lane, ownerToken: null, generation: 0, leaseExpiresAt: null, rerunRequested: false, coalescedCount: 0, lastStartedAt: null, lastCompletedAt: null, lastResultJson: null, updatedAt: now }).onConflictDoNothing();
  const acquired = (await db.update(schema.paperPollLeases).set({
    ownerToken: attempt.ownerToken,
    generation: sql`${schema.paperPollLeases.generation} + 1`,
    leaseExpiresAt: attempt.leaseExpiresAt,
    rerunRequested: false,
    lastStartedAt: now,
    updatedAt: now,
  }).where(and(
    eq(schema.paperPollLeases.lane, lane),
    sql`(${schema.paperPollLeases.ownerToken} IS NULL OR ${schema.paperPollLeases.leaseExpiresAt} IS NULL OR ${schema.paperPollLeases.leaseExpiresAt} <= ${now})`,
  )).returning({ generation: schema.paperPollLeases.generation }))[0];
  if (acquired) return { acquired: true, ownerToken: attempt.ownerToken, generation: acquired.generation };
  const coalesced = (await db.update(schema.paperPollLeases).set({ rerunRequested: true, coalescedCount: sql`${schema.paperPollLeases.coalescedCount} + 1`, updatedAt: now }).where(and(eq(schema.paperPollLeases.lane, lane), sql`${schema.paperPollLeases.ownerToken} IS NOT NULL`)).returning({ ownerToken: schema.paperPollLeases.ownerToken, generation: schema.paperPollLeases.generation }))[0];
  return { acquired: false, activeOwnerToken: coalesced?.ownerToken ?? null, generation: coalesced?.generation ?? 0 };
}

async function claimPaperPollFollowup(ctx: Ctx, lane: PaperPollLane, claim: DurablePaperPollClaim): Promise<DurablePaperPollClaim | null> {
  const now = new Date();
  const row = (await ctx.db<typeof schema>().update(schema.paperPollLeases).set({
    generation: sql`${schema.paperPollLeases.generation} + 1`,
    rerunRequested: false,
    leaseExpiresAt: new Date(now.getTime() + PAPER_POLL_LEASE_MS[lane]),
    updatedAt: now,
  }).where(and(
    eq(schema.paperPollLeases.lane, lane),
    eq(schema.paperPollLeases.ownerToken, claim.ownerToken),
    eq(schema.paperPollLeases.generation, claim.generation),
    eq(schema.paperPollLeases.rerunRequested, true),
  )).returning({ generation: schema.paperPollLeases.generation }))[0];
  return row ? { ownerToken: claim.ownerToken, generation: row.generation } : null;
}

async function completePaperPollLease(ctx: Ctx, lane: PaperPollLane, claim: DurablePaperPollClaim, result: unknown): Promise<boolean> {
  const now = new Date();
  const completed = await ctx.db<typeof schema>().update(schema.paperPollLeases).set({ ownerToken: null, leaseExpiresAt: null, lastCompletedAt: now, lastResultJson: stableJson(result), updatedAt: now }).where(and(
    eq(schema.paperPollLeases.lane, lane),
    eq(schema.paperPollLeases.ownerToken, claim.ownerToken),
    eq(schema.paperPollLeases.generation, claim.generation),
  )).returning({ lane: schema.paperPollLeases.lane });
  return completed.length === 1;
}

async function failPaperPollLease(ctx: Ctx, lane: PaperPollLane, claim: DurablePaperPollClaim, error: unknown): Promise<void> {
  const now = new Date();
  await ctx.db<typeof schema>().update(schema.paperPollLeases).set({ ownerToken: null, leaseExpiresAt: null, lastCompletedAt: now, lastResultJson: stableJson({ ok: false, error: compactError(error, "paper poll failed") }), updatedAt: now }).where(and(
    eq(schema.paperPollLeases.lane, lane),
    eq(schema.paperPollLeases.ownerToken, claim.ownerToken),
    eq(schema.paperPollLeases.generation, claim.generation),
  ));
}

type SchedulerJobKey = "market_data_refresh" | "market_discovery_scan" | "signal_status_monitor" | "history_layer_refresh" | "paper_entry_watch" | "theory_discovery" | "universe_daily_snapshot" | "universe_weekly_refresh" | "signal_daily_postmortem";
const schedulerJobs: ReadonlyArray<{ jobKey: SchedulerJobKey; jobName: string }> = [
  { jobKey: "market_data_refresh", jobName: "crypto-market-data-refresh" },
  { jobKey: "market_discovery_scan", jobName: "crypto-market-discovery" },
  { jobKey: "signal_status_monitor", jobName: "crypto-signal-status-monitor" },
  { jobKey: "history_layer_refresh", jobName: "crypto-history-layer-refresh" },
  { jobKey: "paper_entry_watch", jobName: "crypto-paper-entry-watch" },
  { jobKey: "theory_discovery", jobName: "crypto-theory-discovery" },
  { jobKey: "universe_daily_snapshot", jobName: "crypto-universe-daily-snapshot" },
  { jobKey: "universe_weekly_refresh", jobName: "crypto-universe-weekly-refresh" },
  { jobKey: "signal_daily_postmortem", jobName: "crypto-signal-daily-postmortem" },
];
const schedulerJobKeySchema = z.enum(["market_data_refresh", "market_discovery_scan", "signal_status_monitor", "history_layer_refresh", "paper_entry_watch", "theory_discovery", "universe_daily_snapshot", "universe_weekly_refresh", "signal_daily_postmortem"]);
const schedulerTriggerSchema = z.enum(["scheduler", "manual"]);
type SchedulerTrigger = z.infer<typeof schedulerTriggerSchema>;
const schedulerReceiptSchema = z.object({
  jobKey: schedulerJobKeySchema,
  jobName: z.string(),
  runId: z.string(),
  status: z.enum(["running", "succeeded", "failed"]),
  invokedAt: z.string(),
  completedAt: z.string().nullable(),
  configuredStartupVersion: z.string().nullable(),
  executingVersion: z.string().nullable(),
  triggerProvenance: schedulerTriggerSchema.nullable(),
  progressJson: z.string().nullable(),
  error: z.string().nullable(),
});
const schedulerInvocationsResponse = z.object({
  generatedAt: z.string(),
  jobs: z.array(z.object({ jobKey: schedulerJobKeySchema, jobName: z.string(), latest: schedulerReceiptSchema.nullable() })),
});

function schedulerProgressJson(result: unknown): string | null {
  if (!result || typeof result !== "object" || Array.isArray(result)) return null;
  const counts = (result as Record<string, unknown>).counts;
  return counts && typeof counts === "object" && !Array.isArray(counts) ? JSON.stringify(counts) : null;
}

async function withSchedulerReceipt<T>(ctx: Ctx, jobKey: SchedulerJobKey, claimedTrigger: SchedulerTrigger, work: () => Promise<T>): Promise<T> {
  const job = schedulerJobs.find((candidate) => candidate.jobKey === jobKey);
  if (!job) throw new Error(`Unknown scheduled job ${jobKey}.`);
  const db = ctx.db<typeof schema>();
  const invokedAt = new Date();
  const runId = `${job.jobName}:${invokedAt.toISOString()}:${crypto.randomUUID()}`;
  // Batch 5 A5b: each receipt write is retried once (2s backoff) so one
  // transient write failure cannot cascade into a lost run + a lost
  // failure-record. A second failure throws the original error as before;
  // the underlying receipt-fault diagnosis is a separate queued item.
  await retryOnce(async () => { await db.insert(schema.schedulerInvocationReceipts).values({ jobKey, jobName: job.jobName, runId, status: "running", invokedAt, completedAt: null, deployedVersion: PHASE1_BUILD_ID, triggerProvenance: claimedTrigger, progressJson: null, error: null }); });
  ctx.invalidateQueries();
  try {
    const result = await work();
    await retryOnce(async () => { await db.update(schema.schedulerInvocationReceipts).set({ status: "succeeded", completedAt: new Date(), progressJson: schedulerProgressJson(result), error: null }).where(eq(schema.schedulerInvocationReceipts.runId, runId)); });
    ctx.invalidateQueries();
    return result;
  } catch (error) {
    await retryOnce(async () => { await db.update(schema.schedulerInvocationReceipts).set({ status: "failed", completedAt: new Date(), error: compactError(error, "Scheduler invocation failed") }).where(eq(schema.schedulerInvocationReceipts.runId, runId)); });
    ctx.invalidateQueries();
    throw error;
  }
}

function schedulerReceiptVersions(storedVersion: string | null): { configuredStartupVersion: string | null; executingVersion: string | null } {
  if (!storedVersion) return { configuredStartupVersion: null, executingVersion: null };
  return storedVersion.startsWith("starting-build:")
    ? { configuredStartupVersion: storedVersion, executingVersion: null }
    : { configuredStartupVersion: null, executingVersion: storedVersion };
}

async function readSchedulerInvocations(ctx: Ctx): Promise<z.infer<typeof schedulerInvocationsResponse>> {
  const db = ctx.db<typeof schema>();
  const latestRows = await Promise.all(schedulerJobs.map(async (job) => ({
    job,
    receipt: (await db.select().from(schema.schedulerInvocationReceipts).where(eq(schema.schedulerInvocationReceipts.jobKey, job.jobKey)).orderBy(desc(schema.schedulerInvocationReceipts.invokedAt), desc(schema.schedulerInvocationReceipts.id)).limit(1))[0],
  })));
  return {
    generatedAt: new Date().toISOString(),
    jobs: latestRows.map(({ job, receipt }) => ({
      ...job,
      latest: receipt ? { ...job, runId: receipt.runId, status: receipt.status, invokedAt: receipt.invokedAt.toISOString(), completedAt: receipt.completedAt?.toISOString() ?? null, ...schedulerReceiptVersions(receipt.deployedVersion), triggerProvenance: receipt.triggerProvenance, progressJson: receipt.progressJson, error: receipt.error } : null,
    })),
  };
}

