function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value && typeof value === "object") return `{${Object.entries(value as Record<string, unknown>).sort(([left], [right]) => left.localeCompare(right)).map(([key, nested]) => `${JSON.stringify(key)}:${stableJson(nested)}`).join(",")}}`;
  return JSON.stringify(value) ?? "null";
}
async function sha256Hex(value: string): Promise<string> {
  const bytes = new TextEncoder().encode(value); const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}
function parsePublishedAt(value: string | null, nowMs: number): number | null {
  if (!value) return null;
  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;
  if (normalized === "just now" || normalized === "moments ago") return nowMs;
  if (normalized === "yesterday") return nowMs - DAY;
  const relative = normalized.match(/^(\d+(?:\.\d+)?)\s+(second|minute|hour|day|week|month|year)s?\s+ago$/);
  if (relative) {
    const amount = Number(relative[1]);
    const unit = relative[2];
    const unitMs: Record<string, number> = { second: 1_000, minute: 60_000, hour: 3_600_000, day: DAY, week: 7 * DAY, month: 30 * DAY, year: 365 * DAY };
    const multiplier = unit ? unitMs[unit] : undefined;
    if (Number.isFinite(amount) && multiplier !== undefined) return nowMs - amount * multiplier;
  }
  const absolute = Date.parse(value);
  return Number.isFinite(absolute) ? absolute : null;
}
const LOW_TIER_DOMAINS = new Set(["walletinvestor.com", "thecerbatgem.com"]);
function sourceTier(url: string, title = "", snippet = ""): "STANDARD" | "LOW_TIER" {
  let host = "";
  try { host = new URL(url).hostname.toLowerCase().replace(/^www\./, ""); } catch { return "LOW_TIER"; }
  const text = `${title} ${snippet}`;
  const farmSignals = [/price prediction/i, /\b(?:100x|1000x)\b/i, /presale/i, /bonus up to/i, /##+/, /\bguaranteed returns?\b/i];
  return [...LOW_TIER_DOMAINS].some((domain) => host === domain || host.endsWith(`.${domain}`)) || farmSignals.filter((rx) => rx.test(text)).length >= 2 ? "LOW_TIER" : "STANDARD";
}
function standaloneToken(text: string, token: string): boolean {
  const clean = token.trim(); if (!clean) return false;
  return new RegExp(`(^|[^A-Za-z0-9])${clean.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}([^A-Za-z0-9]|$)`, "i").test(text);
}
function coinIdentityMatches(title: string, snippet: string | null | undefined, name: string, symbol: string): boolean {
  const text = `${title} ${snippet ?? ""}`;
  const normalizedName = name.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  const normalizedText = text.toLowerCase().replace(/[^a-z0-9]+/g, " ");
  return (normalizedName.length >= 3 && normalizedText.includes(normalizedName)) || (symbol.length >= 2 && standaloneToken(text, symbol));
}
async function resolveCoinIdentity(symbol: string, coinId?: string | null, name?: string | null): Promise<{ coinId: string; symbol: string; name: string }> {
  if (coinId) {
    const rows = await getJson(`${CG}/coins/markets?vs_currency=usd&ids=${encodeURIComponent(coinId)}&per_page=1&page=1&sparkline=false`).catch(() => []);
    const row = Array.isArray(rows) ? rows[0] : null;
    return { coinId, symbol: String(row?.symbol ?? symbol).toUpperCase(), name: String(row?.name ?? name ?? symbol) };
  }
  const raw = await getJson(`${CG}/search?query=${encodeURIComponent(symbol)}`);
  const candidates = Array.isArray(raw?.coins) ? raw.coins : [];
  const exact = candidates.filter((row: any) => String(row?.symbol ?? "").toUpperCase() === symbol.toUpperCase()).sort((a: any, b: any) => (finite(a?.market_cap_rank) ?? 999999) - (finite(b?.market_cap_rank) ?? 999999))[0];
  if (!exact?.id) throw new Error(`No canonical CoinGecko identity resolved for ${symbol.toUpperCase()}.`);
  return { coinId: String(exact.id), symbol: String(exact.symbol ?? symbol).toUpperCase(), name: String(exact.name ?? name ?? symbol) };
}
