  const status = results.map((row) => ({ endpoint: row.name, ok: row.ok, status: row.status, reason: row.reason })); const byName = new Map(results.map((row) => [row.name, row]));
  const restricted = results.find((row) => !row.ok && /restricted location|service unavailable from a restricted location|eligible for this service/i.test(row.reason ?? ""));
  const fundingRows = Array.isArray(byName.get("fundingRate")?.data) ? byName.get("fundingRate")?.data : []; const oiRows = Array.isArray(byName.get("openInterestHist")?.data) ? byName.get("openInterestHist")?.data : []; const globalRows = Array.isArray(byName.get("globalLongShortAccountRatio")?.data) ? byName.get("globalLongShortAccountRatio")?.data : []; const takerRows = Array.isArray(byName.get("takerlongshortRatio")?.data) ? byName.get("takerlongshortRatio")?.data : []; const liquidationRows = Array.isArray(byName.get("forceOrders")?.data) ? byName.get("forceOrders")?.data : [];
