  const oiParsed = oiRows.map((row: any) => ({ ts: finite(row.timestamp), usd: finite(row.sumOpenInterestValue) })).filter((row: any) => row.ts !== null && row.usd !== null); const latestOi = oiParsed.at(-1) ?? null; const priorOi = oiParsed.length > 1 ? oiParsed[0] ?? null : null;
