  const fetchedAt = new Date().toISOString();
  const raw = await getJson(`${POLYMARKET_SEARCH}${encodeURIComponent(normalized)}`);
  const rows = flattenPolymarketPayload(raw, fetchedAt, normalized).sort((a, b) => b.overlap - a.overlap || b.volume24hr - a.volume24hr || b.liquidity - a.liquidity);
