function parseStored<T>(value: string, fallback: T): T { try { return JSON.parse(value) as T; } catch { return fallback; } }
// Canonical JSON: key order normalized recursively, so "materially different
// evidence" comparisons ignore key order and whitespace. Two payloads are
// materially different iff their canonical forms differ.
function canonicalJson(value: unknown): string {
  const norm = (v: unknown): unknown => {
    if (Array.isArray(v)) return v.map(norm);
    if (v !== null && typeof v === "object") {
      const out: Record<string, unknown> = {};
      for (const k of Object.keys(v as Record<string, unknown>).sort()) out[k] = norm((v as Record<string, unknown>)[k]);
      return out;
    }
    return v;
  };
  return JSON.stringify(norm(value));
}
