class NamedTimeoutError extends Error {
  constructor(readonly operation: string, readonly timeoutMs: number) { super(`timeout: ${operation} exceeded ${Math.round(timeoutMs / 1000)}s`); this.name = "NamedTimeoutError"; }
}
async function withNamedTimeout<T>(operation: string, timeoutMs: number, work: Promise<T>): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new NamedTimeoutError(operation, timeoutMs)), timeoutMs); });
  try { return await Promise.race([work, timeout]); } finally { if (timer !== undefined) clearTimeout(timer); }
}

