async function fetchHyperliquidFunding(coinId: string, symbol: string, fetchedAt: Date, startTs: number): Promise<Array<{ coinId: string; symbol: string; metric: "funding"; ts: number; value: number; source: string; fetchedAt: Date }>> {
  const upper = symbol.toUpperCase();
  const rows: Array<{ coinId: string; symbol: string; metric: "funding"; ts: number; value: number; source: string; fetchedAt: Date }> = [];
  const sevenDaysAgo = Date.now() - 7 * DAY;
  const cursor = Math.max(sevenDaysAgo, startTs);
  const raw = await postJson(HYPER, { type: "fundingHistory", coin: upper, startTime: cursor });
  const pageRows = Array.isArray(raw) ? raw : [];
  for (const row of pageRows) {
    const ts = finite(row?.time); const value = finite(row?.fundingRate);
    if (ts !== null && value !== null) rows.push({ coinId, symbol: upper, metric: "funding", ts, value, source: "Hyperliquid fundingHistory", fetchedAt });
  }
  return rows;
}

async function ensureHistoryCache(ctx: Ctx, coinId: string, symbol: string, force = false): Promise<{ state: any; bars: HistoryBar[]; funding: Array<{ ts: number; value: number }> }> {
  const db = ctx.db<typeof schema>(); const upper = symbol.toUpperCase(); const def = COVERAGE.find((row) => row.coinId === coinId || row.symbol === upper); const pair = def?.pair ?? null;
  const existing = (await db.select().from(schema.historyCacheState).where(eq(schema.historyCacheState.coinId, coinId)).limit(1))[0] ?? null;
  const today = utcDay(Date.now()); const refreshedToday = existing?.lastRefreshAt instanceof Date && utcDay(existing.lastRefreshAt.getTime()) === today;
  let lastError: string | null = existing?.lastError ?? null;
  let resolvedSource: HistorySource = pair ? (def?.venue === "mexc-spot" ? "mexc" : "binance") : "coingecko";
  if (force || !refreshedToday || !existing?.barCount || Boolean(existing?.lastError)) {
    const refreshErrors: string[] = [];
    // Shared history is an independently idempotent, monotonic cache rather than
    // accepted measurement evidence. Bar/metric identities are unique and
    // immutable (conflicts never rewrite bytes); evaluation revisions copy the
    // exact accepted rows into their own evidence payload. Cache-state metadata
    // is ordered by refresh start so a late response cannot replace a newer one.
    const refreshStartedAt = new Date();
    try {
      const fetchedAt = refreshStartedAt; const bars: HistoryBar[] = [];
      if (pair) {
        let startTime = existing?.lastBarTs ? existing.lastBarTs + DAY : 0;
        for (let page = 0; page < 12; page++) {
          const url = `${BINANCE}/api/v3/klines?symbol=${encodeURIComponent(pair)}&interval=1d&limit=1000&startTime=${Math.max(0, startTime)}`;
          const raw = def?.venue === "mexc-spot" ? await fetchMexcKlines(pair, "1d", Math.max(0, startTime)) : await getJson(url); const rows = Array.isArray(raw) ? raw : [];
          for (const row of rows) {
            const ts = finite(row?.[0]); const close = finite(row?.[4]); if (ts === null || close === null || ts >= Date.now()) continue;
            bars.push({ coinId, symbol: upper, day: utcDay(ts), ts, open: finite(row?.[1]), high: finite(row?.[2]), low: finite(row?.[3]), close, volume: finite(row?.[5]), source: def?.venue === "mexc-spot" ? "mexc" : "binance", fetchedAt });
          }
          const lastTs = finite(rows.at(-1)?.[0]); if (rows.length < 1000 || lastTs === null || lastTs <= startTime) break; startTime = lastTs + DAY; await new Promise((resolve) => setTimeout(resolve, 55));
        }
      } else {
        try {
          // CoinGecko's free API serves bounded daily history. The former `days=max`
          // request is a paid-plan route and returned 401; the market-read path uses
          // this same public market_chart endpoint with a bounded day window.
          const raw = await getJson(`${CG}/coins/${encodeURIComponent(coinId)}/market_chart?vs_currency=usd&days=365&interval=daily`);
          const priceRows = Array.isArray(raw?.prices) ? raw.prices : []; const volumes = new Map<number, number>((Array.isArray(raw?.total_volumes) ? raw.total_volumes : []).map((row: any) => [Number(row?.[0]), Number(row?.[1])]));
          for (const row of priceRows) { const ts = finite(row?.[0]); const close = finite(row?.[1]); if (ts !== null && close !== null && ts < Date.now()) bars.push({ coinId, symbol: upper, day: utcDay(ts), ts, open: null, high: null, low: null, close, volume: finite(volumes.get(ts)), source: "coingecko", fetchedAt }); }
          if (!bars.length) throw new Error(`CoinGecko returned no verified USD daily rows for ${upper}`);
          resolvedSource = "coingecko";
        } catch (coinGeckoError) {
          refreshErrors.push(`CoinGecko free daily history: ${compactError(coinGeckoError, "unavailable")}`);
          throw new Error(`No working source resolved verified USD daily history for ${upper}.`);
        }
      }
      await insertBarChunks(ctx, bars);
      try {
        const cachedFunding = await db.select().from(schema.historicalMetrics).where(eq(schema.historicalMetrics.coinId, coinId)).orderBy(desc(schema.historicalMetrics.ts)).limit(1);
        const fundingRows = await fetchHyperliquidFunding(coinId, upper, fetchedAt, (cachedFunding[0]?.ts ?? -1) + 1);
        await insertMetricChunks(ctx, fundingRows);
      } catch (fundingError) {
        refreshErrors.push(`Hyperliquid funding: ${compactError(fundingError, "history unavailable")}`);
      }
      lastError = refreshErrors.length ? refreshErrors.join(" · ") : null;
    } catch (error) {
      refreshErrors.push(compactError(error, "History source unavailable"));
      lastError = refreshErrors.join(" · ");
    }
    const allBars = await db.select().from(schema.historicalDailyBars).where(eq(schema.historicalDailyBars.coinId, coinId)).orderBy(asc(schema.historicalDailyBars.ts));
    const funding = await db.select().from(schema.historicalMetrics).where(eq(schema.historicalMetrics.coinId, coinId));
    if (allBars.length) resolvedSource = (allBars.at(-1)?.source ?? resolvedSource) as HistorySource;
    const stateValues = { coinId, symbol: upper, source: resolvedSource, firstBarTs: allBars[0]?.ts ?? null, lastBarTs: allBars.at(-1)?.ts ?? null, barCount: allBars.length, fundingCount: funding.length, lastRefreshAt: refreshStartedAt, lastError };
    await db.insert(schema.historyCacheState).values(stateValues).onConflictDoUpdate({
      target: schema.historyCacheState.coinId,
      set: stateValues,
      setWhere: sql`${schema.historyCacheState.lastRefreshAt} IS NULL OR ${schema.historyCacheState.lastRefreshAt} <= ${refreshStartedAt.getTime()}`,
    });
  }
  const bars = await db.select().from(schema.historicalDailyBars).where(eq(schema.historicalDailyBars.coinId, coinId)).orderBy(asc(schema.historicalDailyBars.ts));
  const funding = await db.select().from(schema.historicalMetrics).where(eq(schema.historicalMetrics.coinId, coinId)).orderBy(asc(schema.historicalMetrics.ts));
  const state = (await db.select().from(schema.historyCacheState).where(eq(schema.historyCacheState.coinId, coinId)).limit(1))[0] ?? null;
  return { state, bars: bars.map((row) => ({ ...row, source: row.source as HistorySource, fetchedAt: row.fetchedAt })), funding: funding.map((row) => ({ ts: row.ts, value: row.value })) };
}
// VETO-1 (2026-10-15, revised per Logan item 6): returns the pre-decision
// signal-day candle (CONTEXT ONLY — never a veto) plus the post-decision
// OHLC slice. The slice carries RAW intervals (start >= decisionAt) with
// explicit [start, end) boundaries, the decision-straddling intervals held as
// UNKNOWN-side (never silently assigned), and a coverage report with full
// gap accounting (covered intervals + missing ranges). evaluateBornDead
// classifies intervals against the entry boundary and folds the extremes.
// The completed-day fold still skips every interval with intervalEnd >
// dayStart (grading convention unchanged).
async function loadIssuanceSignalDayCandle(ctx: Ctx, coinId: string, symbol: string, nowMs: number, evaluationNowMs: number = nowMs): Promise<{ candle: SignalDayCandle | null; postDecision: PostDecisionSlice | null }> {
  const cached = await ensureHistoryCache(ctx, coinId, symbol, false);
  const cachedCompleted = completedSignalDayCandle(cached.bars, nowMs);
  const decisionAt = nowMs;
  const windowStart = new Date(decisionAt).toISOString();
  const windowEnd = new Date(evaluationNowMs).toISOString();
  try {
    const raw = await getJson(`${CG}/coins/${encodeURIComponent(coinId)}/ohlc?vs_currency=usd&days=30`);
    const receivedAt = new Date().toISOString();
    const rows = Array.isArray(raw) ? raw : [];
    const dayStart = Math.floor(nowMs / DAY) * DAY;
    const coinGeckoIntervalMs = 4 * HOUR;
    const byDay = new Map<string, { ts: number; open: number; high: number; low: number; close: number; highAt: string | null; lowAt: string | null }>();
    const covering: Array<{ start: number; end: number }> = [];
    const intervals: VetoInterval[] = [];
    const straddlingDecision: VetoInterval[] = [];
    for (const row of rows) {
      const intervalEnd = finite(row?.[0]); const open = finite(row?.[1]); const high = finite(row?.[2]); const low = finite(row?.[3]); const close = finite(row?.[4]);
      if (intervalEnd === null || open === null || high === null || low === null || close === null) continue;
      const intervalStart = intervalEnd - coinGeckoIntervalMs;
      const startIso = new Date(intervalStart).toISOString();
      const endIso = new Date(intervalEnd).toISOString();
      // Coverage collection: intervals whose observation window overlaps the
      // waiting interval [decisionAt, evaluationNowMs) — includes the interval
      // straddling the decision (it starts at or before decisionAt).
      if (intervalEnd > decisionAt && intervalStart < evaluationNowMs) covering.push({ start: intervalStart, end: intervalEnd });
      // Post-decision intervals: fully after the decision. A straddling
      // interval's extreme may have printed pre-decision: UNKNOWN side, held
      // explicitly, never silently assigned to either side (Logan (c)).
      if (intervalStart >= decisionAt) intervals.push({ start: startIso, end: endIso, high, low });
      else if (intervalEnd > decisionAt) straddlingDecision.push({ start: startIso, end: endIso, high, low });
      if (intervalEnd > dayStart) continue;
      const day = utcDay(intervalEnd - 1); const prior = byDay.get(day);
      if (!prior) byDay.set(day, { ts: Math.floor(intervalStart / DAY) * DAY, open, high, low, close, highAt: startIso, lowAt: startIso });
      else byDay.set(day, { ts: prior.ts, open: prior.open, high: high > prior.high ? high : prior.high, highAt: high > prior.high ? startIso : prior.highAt, low: low < prior.low ? low : prior.low, lowAt: low < prior.low ? startIso : prior.lowAt, close });
    }
    const postDecision: PostDecisionSlice = {
      intervals, straddlingDecision,
      receivedAt, venue: VETO_OHLC_VENUE,
      intervalCount: intervals.length,
      coverage: checkIntervalCoverage(covering, decisionAt, evaluationNowMs),
      windowStart, windowEnd,
    };
    const latest = [...byDay.entries()].sort(([left], [right]) => left.localeCompare(right)).at(-1);
    if (!latest) return { candle: cachedCompleted, postDecision };
    const [day, value] = latest;
    const fetchedAt = new Date();
    const existing = cached.bars.find((bar) => bar.day === day) ?? null;
    await ctx.db<typeof schema>().insert(schema.historicalDailyBars).values({ coinId, symbol: symbol.toUpperCase(), day, ts: value.ts, open: value.open, high: value.high, low: value.low, close: value.close, volume: existing?.volume ?? null, source: "coingecko", fetchedAt }).onConflictDoUpdate({ target: [schema.historicalDailyBars.coinId, schema.historicalDailyBars.day], set: { ts: value.ts, open: value.open, high: value.high, low: value.low, close: value.close, source: "coingecko", fetchedAt } });
    return { candle: { day, open: value.open, high: value.high, low: value.low, close: value.close, source: "CoinGecko OHLC → historical_daily_bars grading series", highAt: value.highAt, lowAt: value.lowAt }, postDecision };
  } catch {
    return { candle: cachedCompleted && cachedCompleted.high !== null && cachedCompleted.low !== null ? { ...cachedCompleted, source: `${cachedCompleted.source} historical_daily_bars grading series` } : null, postDecision: null };
  }
}
/**
 * Prospective VETO-1 evidence capture repair. Venue 1m klines add only
 * fully-post-decision, fully-closed intervals; every failure preserves the
 * existing fail-closed slice unchanged.
 */
async function augmentPostDecisionWithVenueKlines(
  coinId: string,
  decisionMs: number,
  quoteMs: number,
  postDecision: PostDecisionSlice | null,
): Promise<PostDecisionSlice | null> {
  const mapped = COVERAGE.find((definition) => definition.coinId === coinId && definition.pair !== null);
  if (!mapped?.pair || !Number.isFinite(decisionMs) || !Number.isFinite(quoteMs) || quoteMs <= decisionMs) return postDecision;
  const venueLabel = mapped.venue === "mexc-spot" ? MEXC_VENUE_LABEL : "Binance Spot";
  const base = mapped.venue === "mexc-spot" ? "https://api.mexc.com/api/v3/klines" : "https://data-api.binance.vision/api/v3/klines";
  const url = `${base}?symbol=${encodeURIComponent(mapped.pair)}&interval=1m&startTime=${decisionMs}&endTime=${quoteMs}&limit=1000`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 7_500);
  try {
    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok) return postDecision;
    const raw: unknown = await response.json();
    const receivedAt = new Date();
    if (!Array.isArray(raw) || raw.length === 0) return postDecision;
    const minuteIntervals: VetoInterval[] = [];
    for (const candidate of raw) {
      if (!Array.isArray(candidate)) continue;
      const klineStart = finite(candidate[0]);
      const high = finite(candidate[2]);
      const low = finite(candidate[3]);
      const providerCloseInclusive = finite(candidate[6]);
      if (klineStart === null || high === null || low === null) continue;
      // Both venues expose closeTime as an inclusive millisecond. Normalize it
      // to this module's [start,end) boundary so adjacent 1m bars tile without
      // inventing a 1ms gap; fall back to the fixed 1m boundary when absent.
      const klineEnd = providerCloseInclusive === null ? klineStart + 60_000 : providerCloseInclusive + 1;
      if (klineStart < decisionMs || klineEnd > quoteMs || klineEnd > receivedAt.getTime() || klineEnd <= klineStart) continue;
      const eventTime = new Date(klineStart).toISOString();
      minuteIntervals.push({
        start: eventTime,
        end: new Date(klineEnd).toISOString(),
        high,
        low,
        observationId: `${mapped.venue}:${mapped.pair}:1m:${klineStart}`,
        venue: mapped.venue,
        eventTime,
        receivedAt: receivedAt.toISOString(),
      });
    }
    if (minuteIntervals.length === 0) return postDecision;
    const combined = [...(postDecision?.intervals ?? []), ...minuteIntervals]
      .filter((interval, index, rows) => rows.findIndex((row) => row.start === interval.start && row.end === interval.end && row.high === interval.high && row.low === interval.low) === index)
      .sort((left, right) => Date.parse(left.start) - Date.parse(right.start));
    const covering = combined.flatMap((interval) => {
      const start = Date.parse(interval.start);
      const end = Date.parse(interval.end);
      return Number.isFinite(start) && Number.isFinite(end) && start >= decisionMs && end <= quoteMs && end > start ? [{ start, end }] : [];
    });
    return {
      intervals: combined,
      straddlingDecision: postDecision?.straddlingDecision ?? [],
      receivedAt: receivedAt.toISOString(),
      venue: venueLabel,
      intervalCount: combined.length,
      coverage: checkIntervalCoverage(covering, decisionMs, quoteMs),
      windowStart: new Date(decisionMs).toISOString(),
      windowEnd: new Date(quoteMs).toISOString(),
    };
  } catch {
    return postDecision;
  } finally {
    clearTimeout(timeout);
  }
}

