  if (/quarter|\bq[1-4]\b|\bmonths?\b|medium[- ]term/.test(value)) return "medium";
  if (/\bhours?\b|\bdays?\b|\bweeks?\b|near[- ]term|short[- ]term|next scheduled/.test(value)) return "short";
