  for (const row of ranked) { if (row.volume <= 0 || selected.some((item) => Math.abs(item.index - row.index) <= 1)) continue; selected.push(row); if (selected.length === 4) break; }
  return selected.map((row) => { const low = Math.exp(logMin + (row.index / bins) * logSpan); const high = Math.exp(logMin + ((row.index + 1) / bins) * logSpan); return { low, high, center: Math.sqrt(low * high), volumeSharePct: totalVolume > 0 ? row.volume / totalVolume * 100 : 0, basis: `Full-history log-price volume bin; ${(totalVolume > 0 ? row.volume / totalVolume * 100 : 0).toFixed(2)}% of observed source volume.` }; }).sort((a, b) => a.center - b.center);
