async function theoryViews(ctx: Ctx, rows: Array<typeof schema.theoryWatch.$inferSelect>, options: { includeInsufficientEvidence?: boolean } = {}): Promise<any[]> {
  const symbols = [...new Set(rows.map((row) => row.linkedSymbol.toUpperCase()).filter(Boolean))]; const db = ctx.db<typeof schema>();
  const [allBars, states] = symbols.length ? await Promise.all([db.select().from(schema.historicalDailyBars).where(inArray(schema.historicalDailyBars.symbol, symbols)).orderBy(asc(schema.historicalDailyBars.ts)), db.select().from(schema.historyCacheState).where(inArray(schema.historyCacheState.symbol, symbols))]) : [[], []];
  const barsBySymbol = new Map<string, HistoryBar[]>(); for (const bar of allBars) { const list = barsBySymbol.get(bar.symbol) ?? []; list.push({ ...bar, source: bar.source as HistorySource }); barsBySymbol.set(bar.symbol, list); }
  const stateBySymbol = new Map(states.map((row) => [row.symbol, row]));
  return rows.map((row) => ({ row, snapshot: parseStored<any>(row.snapshotJson, {}) })).filter(({ snapshot }) => options.includeInsufficientEvidence === true || snapshot?.evidenceAssessment?.insufficientEvidence !== true).map(({ row, snapshot }) => ({ ...row, layers: parseStored(row.layersJson, []), sources: parseStored(row.sourcesJson, []), snapshot, positioning: buildTheoryPositioning(barsBySymbol.get(row.linkedSymbol.toUpperCase()) ?? [], stateBySymbol.get(row.linkedSymbol.toUpperCase()) ?? null, row), createdAt: row.createdAt.toISOString(), lastCheckedAt: row.lastCheckedAt.toISOString(), invalidatedAt: row.invalidatedAt?.toISOString() ?? null }));
}
// Withdrawn theories stay visible in explicitly labeled history: the view
// carries the withdrawal record (reason, evidence, timestamp) so the original
