      const crowdLayer = await buildCrowdPricingLayer({ headline: row.headline, thesis: row.thesis, sector: row.sector, linkedSymbol: row.linkedSymbol, direction: row.direction });
      const assessment = scoreTheoryLayers([...parseStored<any[]>(row.layersJson, []).filter((layer) => layer.name !== "CROWD PRICING"), crowdLayer], row.direction as TheoryDirection); const layers = assessment.layers;
      await db.update(schema.theoryWatch).set({ layersJson: JSON.stringify(layers), confidence: assessment.confidence, snapshotJson: JSON.stringify({ ...snapshot, sourceIntegrity, crowdPricing: crowdLayer, crowdPricingCheckedAt: now.toISOString(), evidenceAssessment: assessment }), lastCheckedAt: now }).where(eq(schema.theoryWatch.id, row.id));
