async function loadPaperBandReliability(ctx: Ctx, score: number): Promise<BandReliabilityInput> {
  const rows = await ctx.db<typeof schema>().select().from(schema.paperModelComparisons).where(and(eq(schema.paperModelComparisons.cohort, "prospective_issued"), eq(schema.paperModelComparisons.outcomeStatus, "complete"))).limit(5000);
  const observations: RatingObservation[] = rows.flatMap((row) => {
    if (row.productionScore === null) return [];
    const outcome = parseStored<Record<string, unknown>>(row.outcomeJson ?? "{}", {});
    const r = finite(outcome.netR ?? outcome.r ?? outcome.realizedR);
    return r === null ? [] : [{ score: Math.abs(row.productionScore), won: r > 0, horizon: 30, r }];
  });
  const reliability = ratingReliability(score, observations, "paper signal · frozen production model closed outcome");
  return { bandKey: reliability.band, killFlag: reliability.killFlag, status: reliability.status, sampleSize: reliability.sampleSize, expectancyR: reliability.expectancyR };
}


type PaperCycleResultRow = { candidateKey: string; symbol: string; state: string; reasonCode: string | null; reason: string | null; paperSignalId: string | null };
type PaperHandoffCandidateRow = typeof schema.paperHandoffCandidates.$inferSelect;
type PaperHandoffRunRow = typeof schema.paperHandoffRuns.$inferSelect;

function paperCandidateWindow(row: PaperHandoffCandidateRow, handoff: PaperHandoffRunRow, fallback: Date): { decisionAt: Date; entryExpiresAt: Date } {
  const evidence = parseStored<Record<string, unknown>>(row.decisionEvidenceJson, {});
  const capturedAtMs = typeof evidence.capturedAt === "string" ? Date.parse(evidence.capturedAt) : Number.NaN;
  const decisionAt = new Date(Number.isFinite(capturedAtMs) ? capturedAtMs : handoff.completedAt?.getTime() ?? fallback.getTime());
  return { decisionAt, entryExpiresAt: new Date(decisionAt.getTime() + PAPER_ENTRY_WINDOW_MS) };
}

async function syncPaperCandidateIntake(ctx: Ctx, freezeVersion: string, now: Date): Promise<void> {
  const db = ctx.db<typeof schema>();
  const handoffs = await db.select().from(schema.paperHandoffRuns).where(eq(schema.paperHandoffRuns.status, "complete")).orderBy(asc(schema.paperHandoffRuns.id));
  if (!handoffs.length) return;
  const handoffById = new Map(handoffs.map((row) => [row.id, row]));
  const eligible = await db.select().from(schema.paperHandoffCandidates).where(eq(schema.paperHandoffCandidates.outcome, "eligible")).orderBy(asc(schema.paperHandoffCandidates.handoffRunId), asc(schema.paperHandoffCandidates.id));
  const existingPaper = await db.select({ candidateKey: schema.paperSignalCandidates.candidateKey, state: schema.paperSignalCandidates.state, reasonCode: schema.paperSignalCandidates.reasonCode, reason: schema.paperSignalCandidates.reason }).from(schema.paperSignalCandidates);
  const existingByKey = new Map(existingPaper.map((row) => [row.candidateKey, row]));
  for (let ordinal = 0; ordinal < eligible.length; ordinal++) {
    const row = eligible[ordinal];
    if (!row) continue;
    const handoff = handoffById.get(row.handoffRunId);
    if (!handoff) continue;
    const canonicalKey = `${freezeVersion}:${row.candidateKey}`;
    const persisted = existingByKey.get(canonicalKey) ?? null;
    const window = paperCandidateWindow(row, handoff, now);
    const historicalUnprocessed = !persisted && (handoff.completedAt?.getTime() ?? handoff.createdAt.getTime()) < PAPER_INTAKE_REPAIR_ACTIVATED_AT.getTime();
    const status = persisted ? "processed" as const : historicalUnprocessed ? "missed_processing" as const : "queued" as const;
    const reasonCode = persisted?.reasonCode ?? (historicalUnprocessed ? "missed-processing" : null);
    const reason = persisted?.reason ?? (historicalUnprocessed ? "The candidate was eligible before the durable intake repair but received no paper-processing row. It remains missed-processing; its expired historical opportunity is not reopened and its hypothetical outcome is unknown." : null);
    await db.insert(schema.paperCandidateIntake).values({
      handoffCandidateId: row.id,
      handoffRunId: row.handoffRunId,
      discoveryRunId: row.discoveryRunId,
      candidateKey: canonicalKey,
      batchOrdinal: ordinal,
      status,
      outcome: persisted?.state ?? (historicalUnprocessed ? "missed-processing" : null),
      reasonCode,
      reason,
      decisionAt: window.decisionAt,
      entryExpiresAt: window.entryExpiresAt,
      attemptCount: 0,
      claimedBy: null,
      leaseExpiresAt: null,
      completedAt: status === "queued" ? null : now,
      createdAt: now,
      updatedAt: now,
    }).onConflictDoNothing();
  }
}

