function simpleHash(value: string): string {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) hash = Math.imul(hash ^ value.charCodeAt(i), 16777619);
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function symbolMatches(raw: unknown, symbol: string): boolean {
  const normalized = String(raw ?? "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  return normalized === symbol || normalized === `${symbol}USD` || normalized === `${symbol}USDT` || normalized.split(/USD|USDT/)[0] === symbol;
}

async function ensureCoreAssetProfiles(ctx: Ctx): Promise<void> {
  const db = ctx.db<typeof schema>();
  const now = new Date();
  for (const profile of CORE_ASSET_PROFILES) {
    await db.insert(schema.assetProfiles).values({ ...profile, updatedAt: now }).onConflictDoNothing();
  }
}

async function loadAssetContext(ctx: Ctx, args: { symbol: string; assetId?: string; flow?: string; auditRead?: boolean }): Promise<AssetContextSummary | null> {
  await ensureCoreAssetProfiles(ctx);
  const db = ctx.db<typeof schema>();
  const symbol = args.symbol.toUpperCase();
  const profiles = await db.select().from(schema.assetProfiles);
  const profile = profiles.find((row) => row.symbol.toUpperCase() === symbol || row.assetId === args.assetId) ?? null;
  if (!profile) return null;
  // Withdrawn theories are excluded from lead selection and summaries below, and
  // surfaced in explicitly labeled history. The original theory rows are never
  // modified or deleted.
  const [allTheories, allNews, allContracts, allEvents, assessments, contextLinks, allLinkedResearch, withdrawalRows] = await Promise.all([
    // Deterministic ordering: lastCheckedAt desc, then id asc as the tie-break.
    // This tie-break governs CURRENT reads only; it does NOT retroactively
    // establish which theory led at any historical decision time.
    db.select().from(schema.theoryWatch).orderBy(desc(schema.theoryWatch.lastCheckedAt), asc(schema.theoryWatch.id)).limit(500),
    db.select().from(schema.discoveryNews).orderBy(desc(schema.discoveryNews.retrievedAt)).limit(500),
    db.select().from(schema.signalContracts).orderBy(desc(schema.signalContracts.decisionAt)).limit(500),
    db.select().from(schema.paperAlertEvents).orderBy(desc(schema.paperAlertEvents.updatedAt)).limit(500),
    db.select().from(schema.assetAssessments).where(eq(schema.assetAssessments.assetId, profile.assetId)).orderBy(desc(schema.assetAssessments.decisionAt)).limit(20),
    db.select().from(schema.assetContextLinks).where(eq(schema.assetContextLinks.assetId, profile.assetId)).limit(1000),
    db.select().from(schema.assetResearchRecords).orderBy(desc(schema.assetResearchRecords.observedAt)).limit(500),
    db.select().from(schema.theoryWithdrawals),
  ]);
  const linkedResearchIds = new Set(contextLinks.filter((row) => row.sourceType === "linked_research").map((row) => row.sourceId));
  const linkedResearch = allLinkedResearch.filter((row) => linkedResearchIds.has(String(row.id)));
  const withdrawnTheoryIds = new Set(withdrawalRows.map((row) => row.theoryId));
  const withdrawnTheories = allTheories.filter((row) => symbolMatches(row.linkedSymbol, symbol) && withdrawnTheoryIds.has(row.id));
  const theories = allTheories.filter((row) => symbolMatches(row.linkedSymbol, symbol) && !withdrawnTheoryIds.has(row.id));
  const news = allNews.filter((row) => {
    const tags = parseStored<unknown[]>(row.assetTagsJson, []);
    return tags.some((tag) => typeof tag === "string" && symbolMatches(tag, symbol));
  });
  const contracts = allContracts.filter((row) => symbolMatches(row.symbol, symbol) || row.assetId === profile.assetId);
  const contract = contracts[0] ?? null;
  const delivery = contract ? allEvents.find((row) => row.paperSignalId === contract.signalId || row.contractId === contract.signalId) ?? null : null;
  const coinIds = symbol === "BTC" ? ["bitcoin", "btc"] : symbol === "NEAR" ? ["near", "near-protocol"] : [];
  const snapshotRows = coinIds.length ? await db.select().from(schema.marketSnapshots).where(inArray(schema.marketSnapshots.coinId, coinIds)).orderBy(desc(schema.marketSnapshots.capturedAt)).limit(1) : [];
  const snapshot = snapshotRows[0] ?? null;
  const outcomeRows = assessments.length ? await db.select().from(schema.assetAssessmentOutcomes).where(inArray(schema.assetAssessmentOutcomes.assessmentId, assessments.map((row) => row.id))) : [];
  const leadTheory = theories[0] ?? null;
  const leadNews = news[0] ?? null;
  const leadResearch = linkedResearch[0] ?? null;
  const leadVerifiedResearch = linkedResearch.find((row) => row.evidenceClass === "verified") ?? null;
  const surfaced = leadVerifiedResearch ? `${leadVerifiedResearch.title} (${leadVerifiedResearch.originKind.replaceAll("_", " ")}, observed ${leadVerifiedResearch.observedAt.toISOString()}).` : leadNews ? `${leadNews.title}. ${leadNews.whyItMatters}` : leadTheory ? `${leadTheory.headline}.` : leadResearch ? `${leadResearch.title} (${leadResearch.evidenceClass}; context only).` : contract ? `${contract.direction.toUpperCase()} paper setup recorded at ${contract.decisionAt.toISOString()}.` : "No linked catalyst or measured signal is stored yet.";
  const logic = leadTheory?.thesis ?? leadNews?.whyItMatters ?? leadVerifiedResearch?.body ?? (contract ? `The stored ${contract.direction} setup is a paper observation; its price path is evaluated against its fixed entry, stop and target.` : "No causal thesis is stored yet.");
  const contextOnly = linkedResearch.find((row) => row.evidenceClass !== "verified");
  const disagreeParts = [leadTheory?.countercase, leadTheory?.status === "invalidated" ? leadTheory.invalidationReason : null, contextOnly ? `${contextOnly.title} is ${contextOnly.evidenceClass} context and is excluded from frozen scores.` : null, leadTheory ? `Theory checked ${leadTheory.lastCheckedAt.toISOString()}.` : null, !leadTheory && !leadNews && !linkedResearch.length ? "No linked contrary-evidence record is available." : null].filter((part): part is string => Boolean(part));
  const nextParts = [leadTheory?.invalidation ? `Invalidates: ${leadTheory.invalidation}` : null, leadTheory?.forwardLook ? `Watch: ${leadTheory.forwardLook}` : null, contract ? `Recheck no later than ${contract.expiresAt.toISOString()}.` : null, !leadTheory && !contract ? "Link a falsifiable theory or paper signal before acting." : null].filter((part): part is string => Boolean(part));
  const sources: AssetContextSummary["sources"] = [{ label: `${profile.name} reference`, url: profile.sourceUrl, observedAt: profile.verifiedAt.toISOString() }];
  for (const row of theories.slice(0, 5)) {
    const parsed = parseStored<Array<{ title?: string; url?: string; observedAt?: string } | string>>(row.sourcesJson, []);
    parsed.slice(0, 3).forEach((source, index) => sources.push({ label: typeof source === "string" ? source : source.title ?? `${row.headline} source ${index + 1}`, url: typeof source === "object" && typeof source.url === "string" ? source.url : null, observedAt: typeof source === "object" && typeof source.observedAt === "string" ? source.observedAt : row.lastCheckedAt.toISOString() }));
  }
  news.slice(0, 5).forEach((row) => sources.push({ label: `${row.source}: ${row.title}`, url: row.url, observedAt: row.publishedAt ?? row.retrievedAt.toISOString() }));
  linkedResearch.slice(0, 8).forEach((row) => sources.push({ label: `${row.sourcePublisher}: ${row.title} · ${row.evidenceClass}${row.evidenceClass === "verified" ? "" : " · context only"}`, url: row.sourceUrl, observedAt: row.observedAt.toISOString() }));
  const contextAsOf = [snapshot?.capturedAt, leadTheory?.lastCheckedAt, leadNews?.retrievedAt, contract?.decisionAt, leadResearch?.observedAt].filter((value): value is Date => value instanceof Date).sort((a, b) => b.getTime() - a.getTime())[0] ?? profile.verifiedAt;
  const evidence: AssetContextSummary["evidence"] = [
    ...theories.slice(0, 8).map((row) => ({ type: "theory", id: String(row.id), title: row.headline, observedAt: row.lastCheckedAt.toISOString(), stance: row.status === "invalidated" ? "challenging" : row.status === "contested" ? "neutral" : "supporting", evidenceClass: "verified" as const, scoreEligible: false })),
    ...news.slice(0, 8).map((row) => ({ type: "news", id: String(row.id), title: row.title, observedAt: row.publishedAt ?? row.retrievedAt.toISOString(), stance: "neutral", evidenceClass: "verified" as const, scoreEligible: false })),
    ...linkedResearch.slice(0, 12).map((row) => ({ type: row.originKind, id: String(row.id), title: row.title, observedAt: row.observedAt.toISOString(), stance: "neutral", evidenceClass: row.evidenceClass, scoreEligible: false })),
  ].sort((a, b) => b.observedAt.localeCompare(a.observedAt));
  // Withdrawn theories remain inspectable in explicitly labeled history; they
  // never lead summaries and their reasoning is excluded above.
  const withdrawnHistory = withdrawnTheories.slice(0, 8).map((row) => {
    const withdrawal = withdrawalRows.find((w) => w.theoryId === row.id);
    return { type: "theory", id: String(row.id), title: row.headline, observedAt: row.lastCheckedAt.toISOString(), stance: "withdrawn" as const, evidenceClass: "verified" as const, scoreEligible: false, withdrawal: withdrawal ? { reason: withdrawal.reason, evidence: parseStored(withdrawal.evidenceJson, {}), withdrawnAt: withdrawal.withdrawnAt.toISOString(), withdrawnBy: withdrawal.withdrawnBy } : null };
  });
  const summary: AssetContextSummary = {
    assetId: profile.assetId, symbol: profile.symbol, name: profile.name, assetKind: profile.assetKind, instrument: profile.instrument,
    what: `${profile.description} ${profile.economicModel} Instrument: ${profile.instrument}.`, why: surfaced, logic,
    disagrees: disagreeParts.join(" "), next: nextParts.join(" "),
    price: { value: snapshot?.price ?? contract?.entryPrice ?? null, capturedAt: snapshot?.capturedAt.toISOString() ?? contract?.decisionAt.toISOString() ?? null },
    signal: { status: contract?.issuanceState ?? "none", direction: contract?.direction ?? null, decisionAt: contract?.decisionAt.toISOString() ?? null },
    delivery: { status: delivery?.status ?? (contract ? "not_enqueued" : "none"), acknowledgedAt: delivery?.acknowledgedAt?.toISOString() ?? null },
    sources, calculations: [
      { label: "Price", detail: snapshot ? `Stored market snapshot captured ${snapshot.capturedAt.toISOString()}.` : contract ? `No newer market snapshot; showing the paper contract entry price recorded ${contract.decisionAt.toISOString()}.` : "No stored price is linked." },
      { label: "Signal", detail: contract ? `${contract.direction.toUpperCase()} · score ${contract.setupScore.toFixed(1)} · entry ${contract.entryPrice} · stop ${contract.stopPrice} · target ${contract.targetPrice}.` : "No stored paper signal contract is linked." },
      { label: "Delivery", detail: delivery ? `${delivery.status}; ${delivery.acknowledgedAt ? `acknowledged ${delivery.acknowledgedAt.toISOString()}` : "no acknowledgement stored"}.` : "No stored delivery event is linked." },
    ], evidence, dataAsOf: contextAsOf.toISOString(),
    withdrawnTheories: withdrawnHistory,
    history: assessments.map((row) => ({ assessmentKey: row.assessmentKey, flow: row.flow, decisionAt: row.decisionAt.toISOString(), outcomes: outcomeRows.filter((outcome) => outcome.assessmentId === row.id).map((outcome) => ({ outcomeType: outcome.outcomeType, content: parseStored(outcome.outcomeJson, {}), evidence: parseStored(outcome.evidenceJson, {}), observedAt: outcome.observedAt.toISOString() })) })), 
  };
  const now = new Date();
  const linkRows = [
    ...theories.map((row) => ({ assetId: profile.assetId, sourceType: "theory_watch" as const, sourceId: String(row.id), stance: (row.status === "invalidated" ? "challenging" : row.status === "contested" ? "neutral" : "supporting") as "supporting" | "challenging" | "neutral", eventAt: row.lastCheckedAt, linkedAt: now })),
    ...news.map((row) => ({ assetId: profile.assetId, sourceType: "discovery_news" as const, sourceId: String(row.id), stance: "neutral" as const, eventAt: row.retrievedAt, linkedAt: now })),
    ...contracts.map((row) => ({ assetId: profile.assetId, sourceType: "signal_contract" as const, sourceId: row.signalId, stance: "neutral" as const, eventAt: row.decisionAt, linkedAt: now })),
  ];
  for (const link of linkRows) await db.insert(schema.assetContextLinks).values(link).onConflictDoNothing();
  if (args.auditRead) await db.insert(schema.assetResearchContextReads).values({ assetId: profile.assetId, flow: args.flow ?? "unknown", contextHash: simpleHash(JSON.stringify(summary)), theoryCount: theories.length, newsCount: news.length, retrievedAt: now });
  return summary;
}

// ---------------------------------------------------------------------------
// Batch 2 — discovery funnel instrumentation (MEASUREMENT ONLY).
// These helpers only WRITE append-only counters at run completion (after all
// decisions for the run are final) and READ them back verbatim. No gate,
// threshold, weight, tier, door, scoring, or issuance decision reads the
// discovery_funnel_counts table; nothing in any decision path calls these.
// ---------------------------------------------------------------------------
type FunnelRowInput = { stage: string; gate: string | null; reasonCode: string; count: number };

async function writeDiscoveryFunnelCounts(ctx: Ctx, args: { runId: number; runKind: "discovery" | "issuance"; rows: FunnelRowInput[]; computedAt: Date }): Promise<void> {
  const db = ctx.db<typeof schema>();
  const existing = (await db.select({ id: schema.discoveryFunnelCounts.id }).from(schema.discoveryFunnelCounts).where(and(eq(schema.discoveryFunnelCounts.runKind, args.runKind), eq(schema.discoveryFunnelCounts.runId, args.runId))).limit(1))[0];
  if (existing) return; // append-only: rows are inserted once at run completion, never rewritten
  const values = args.rows.filter((row) => Number.isFinite(row.count) && row.count >= 0).map((row) => ({ runId: args.runId, runKind: args.runKind, stage: row.stage, gate: row.gate, reasonCode: row.reasonCode, count: Math.round(row.count), computedAt: args.computedAt }));
  if (!values.length) return;
  await db.insert(schema.discoveryFunnelCounts).values(values);
}

// ---------------------------------------------------------------------------
// Evidence captures (migration 0067, PAPER ONLY — measurement only).
// CHANGE A: per-asset ATH gate records. CHANGE B: decision-time drift
// reference capture. Both are additive and FAIL-ISOLATED: every write/fetch
// here is wrapped so a failure can never fail a discovery run, block a
// candidate, or alter any existing output, field, or count. No gate,
// threshold, scoring, veto, venue mapping, issuance behavior, or production
// decision ever reads either capture.
// ---------------------------------------------------------------------------
type AthGateRecordInput = {
  coinId: string; symbol: string;
  athDistancePct: number | null; athValue: number | null; athDate: string | null;
  athRuleFired: boolean; velocityBypassApplied: boolean;
  disposition: "excluded_by_ath_gate" | "bypassed_velocity" | "passed";
};

async function writeAthGateRecords(ctx: Ctx, discoveryRunId: number, records: AthGateRecordInput[], evaluatedAt: Date): Promise<void> {
  // Fail-isolated by contract: this function never throws.
  try {
    if (!records.length) return;
    const db = ctx.db<typeof schema>();
    const values = records.map((row) => ({
      discoveryRunId, coinId: row.coinId, symbol: row.symbol, evaluatedAt,
      athDistancePct: row.athDistancePct, athValue: row.athValue, athDate: row.athDate,
      athRuleFired: row.athRuleFired, velocityBypassApplied: row.velocityBypassApplied,
      disposition: row.disposition,
    }));
    for (let i = 0; i < values.length; i += 100) {
      const chunk = values.slice(i, i + 100);
      if (!chunk.length) continue;
      try {
        await db.insert(schema.discoveryAthGateRecords).values(chunk);
      } catch {
        // Chunk failed (e.g. a transient lock): fall back to per-row inserts
        // for this chunk only; a single bad row must not lose the rest, and
        // a total failure must not fail the run.
        for (const row of chunk) {
          try { await db.insert(schema.discoveryAthGateRecords).values(row); } catch { /* evidence capture only */ }
        }
      }
    }
  } catch { /* evidence capture only — never fails the run */ }
}

async function sha256HexOfText(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

const DRIFT_CAPTURE_TIMEOUT_MS = 8_000;
const DRIFT_CAPTURE_WINDOW_MS = 900_000;
const DRIFT_CAPTURE_MAX_ATTEMPTS = 2;
const DRIFT_CAPTURE_RETRY_PAUSE_MS = 500;
const DRIFT_CAPTURE_BLOCK_BUDGET_MS = 45_000;

// CHANGE B: fetch Binance Spot aggTrades over [observationMs - 900s,
// observationMs] and keep the last print at or before the observation time.
// Returns the JSON string to persist as driftReferenceCaptureJson. Never
// throws and never blocks a candidate. Non-Binance-Spot mappings get
// {status:"unsupported_venue"}; any fetch failure / empty window gets
// {status:"unavailable", reason}.
//
// Bounded resilience repair (2026-10-21): the capture was the artifact's
// only bare-fetch call — a single attempt under a hard 5s abort with no
// User-Agent — while the route's measured healthy latency is 1.6–3.6s, so
// the cap sat inside normal variance (run 141 lost every capture to
// aborts). Now: up to 2 attempts of <=8s each, retrying once after a 500ms
// pause ONLY on abort/timeout, HTTP 429, or HTTP >= 500; every other
// outcome returns immediately with the original reason vocabulary. A
// whole-block budget of 45s (measured from the capture block's start at
// the call site) skips candidates whose FIRST attempt would start late:
// they record {status:"unavailable", reason:"budget_exceeded"} and are
// never fetched; in-flight attempts finish. Records gain additive fields
// only: "attempts" on every record, and "fetchStartedAt" on unavailable
// records (first attempt's start, or null when no attempt was made).
// fetchStartedAt on a success after a retry is the FIRST attempt's start.
async function captureDriftReference(args: { coinId: string; symbol: string; observationMs: number; blockStartedAtMs?: number }): Promise<string> {
  const coverage = COVERAGE.find((item) => item.coinId === args.coinId || item.symbol === args.symbol.toUpperCase()) ?? null;
  if (!coverage || coverage.venue !== "binance-spot" || !coverage.pair) return stableJson({ status: "unsupported_venue", attempts: 0, fetchStartedAt: null });
  if (args.blockStartedAtMs !== undefined && Date.now() - args.blockStartedAtMs > DRIFT_CAPTURE_BLOCK_BUDGET_MS) {
    return stableJson({ status: "unavailable", reason: "budget_exceeded", fetchStartedAt: null, attempts: 0 });
  }
  const pair = coverage.pair;
  const startTime = Math.trunc(args.observationMs - DRIFT_CAPTURE_WINDOW_MS);
  const endTime = Math.trunc(args.observationMs);
  const url = `${BINANCE}/api/v3/aggTrades?symbol=${encodeURIComponent(pair)}&startTime=${startTime}&endTime=${endTime}&limit=1000`;
  let firstFetchStartedAt: Date | null = null;
  let attempts = 0;
  while (attempts < DRIFT_CAPTURE_MAX_ATTEMPTS) {
    if (attempts > 0) await new Promise<void>((resolve) => setTimeout(resolve, DRIFT_CAPTURE_RETRY_PAUSE_MS));
    attempts += 1;
    const attemptStartedAt = new Date();
    if (!firstFetchStartedAt) firstFetchStartedAt = attemptStartedAt;
    const fetchStartedIso = (firstFetchStartedAt ?? attemptStartedAt).toISOString();
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), DRIFT_CAPTURE_TIMEOUT_MS);
    try {
      const response = await fetch(url, { headers: { Accept: "application/json", "User-Agent": "MuseAltcoinTerminal/1.0" }, signal: controller.signal });
      const raw = await response.text();
      const fetchReceivedAt = new Date();
      if (!response.ok) {
        const retryableStatus = response.status === 429 || response.status >= 500;
        if (retryableStatus && attempts < DRIFT_CAPTURE_MAX_ATTEMPTS) continue;
        return stableJson({ status: "unavailable", reason: `http_${response.status}`, fetchStartedAt: fetchStartedIso, attempts });
      }
      const responseHash = await sha256HexOfText(raw);
      let parsed: unknown;
      try { parsed = JSON.parse(raw); } catch { return stableJson({ status: "unavailable", reason: "malformed_response", fetchStartedAt: fetchStartedIso, attempts }); }
      if (!Array.isArray(parsed)) return stableJson({ status: "unavailable", reason: "malformed_response", fetchStartedAt: fetchStartedIso, attempts });
      let best: { price: number; tradeId: string; ts: number; seq: number } | null = null;
      for (const item of parsed) {
        if (!item || typeof item !== "object") continue;
        const row = item as Record<string, unknown>;
        const ts = Number(row.T); const price = Number(row.p); const seq = Number(row.a);
        if (!Number.isFinite(ts) || !Number.isFinite(price) || price <= 0 || ts > args.observationMs) continue;
        if (!best || ts > best.ts || (ts === best.ts && Number.isFinite(seq) && seq > best.seq)) {
          best = { price, tradeId: typeof row.a === "string" || typeof row.a === "number" ? String(row.a) : "", ts, seq: Number.isFinite(seq) ? seq : 0 };
        }
      }
      if (!best) return stableJson({ status: "unavailable", reason: "no_print_in_window", fetchStartedAt: fetchStartedIso, attempts });
      return stableJson({
        referencePrice: best.price,
        venueTradeId: best.tradeId,
        printTimestamp: new Date(best.ts).toISOString(),
        fetchStartedAt: fetchStartedIso,
        fetchReceivedAt: fetchReceivedAt.toISOString(),
        responseHash,
        attempts,
      });
    } catch (error) {
      const reason = error instanceof Error && error.name === "AbortError" ? "timeout" : "fetch_failed";
      if (reason === "timeout" && attempts < DRIFT_CAPTURE_MAX_ATTEMPTS) continue;
      return stableJson({ status: "unavailable", reason, fetchStartedAt: fetchStartedIso, attempts });
    } finally {
      clearTimeout(timer);
    }
  }
  // Unreachable: every loop path returns or retries within the attempt cap.
  return stableJson({ status: "unavailable", reason: "fetch_failed", fetchStartedAt: firstFetchStartedAt?.toISOString() ?? null, attempts });
}

const discoveryFunnelResponse = z.object({
  instrumented: z.boolean(),
  runId: z.number().nullable(),
  runKind: z.enum(["discovery", "issuance"]),
  computedAt: z.string().nullable(),
  stages: z.array(z.object({
    stage: z.string(),
    input: z.number(),
    survivors: z.number(),
    removals: z.array(z.object({ gate: z.string().nullable(), reasonCode: z.string(), count: z.number(), diagnostic: z.boolean() })),
    breakdown: z.array(z.object({ gate: z.string().nullable(), count: z.number() })),
  })),
  recentRuns: z.array(z.object({ runId: z.number(), runKind: z.string(), computedAt: z.string() })),
});
type DiscoveryFunnelResponse = z.infer<typeof discoveryFunnelResponse>;

const FUNNEL_STAGE_ORDER: Record<string, number> = { S0: 0, S1: 1, S2: 2, S3: 3, S4: 4, S5: 5, S6: 6, issuance: 7 };

async function readDiscoveryFunnel(ctx: Ctx, args: { runId?: number; runKind?: "discovery" | "issuance" }): Promise<DiscoveryFunnelResponse> {
  const db = ctx.db<typeof schema>();
  const runKind = args.runKind ?? "discovery";
  const runRows = await db.select({ runId: schema.discoveryFunnelCounts.runId, computedAt: schema.discoveryFunnelCounts.computedAt }).from(schema.discoveryFunnelCounts).where(eq(schema.discoveryFunnelCounts.runKind, runKind)).orderBy(desc(schema.discoveryFunnelCounts.runId));
  const seen = new Map<number, Date>();
  for (const row of runRows) if (!seen.has(row.runId)) seen.set(row.runId, row.computedAt);
  const recentRuns = [...seen.entries()].slice(0, 10).map(([runId, computedAt]) => ({ runId, runKind, computedAt: computedAt.toISOString() }));
  const resolvedRunId = args.runId ?? recentRuns[0]?.runId ?? null;
  if (resolvedRunId === null) return { instrumented: false, runId: null, runKind, computedAt: null, stages: [], recentRuns };
  const rows = await db.select().from(schema.discoveryFunnelCounts).where(and(eq(schema.discoveryFunnelCounts.runKind, runKind), eq(schema.discoveryFunnelCounts.runId, resolvedRunId))).orderBy(asc(schema.discoveryFunnelCounts.id));
  if (!rows.length) return { instrumented: false, runId: resolvedRunId, runKind, computedAt: null, stages: [], recentRuns };
  const computedAt = rows.reduce((latest, row) => (row.computedAt.getTime() > latest.getTime() ? row.computedAt : latest), rows[0]?.computedAt ?? new Date(0));
  const byStage = new Map<string, typeof rows>();
  for (const row of rows) byStage.set(row.stage, [...(byStage.get(row.stage) ?? []), row]);
  const stages = [...byStage.entries()]
    .sort(([a], [b]) => (FUNNEL_STAGE_ORDER[a] ?? 99) - (FUNNEL_STAGE_ORDER[b] ?? 99))
    .map(([stage, stageRows]) => {
      const survivorRows = stageRows.filter((row) => row.reasonCode === "survivors");
      const survivors = survivorRows.reduce((sum, row) => sum + row.count, 0);
      const breakdown = survivorRows.filter((row) => row.gate !== null).map((row) => ({ gate: row.gate, count: row.count }));
      const removals = stageRows.filter((row) => row.reasonCode !== "survivors").map((row) => ({ gate: row.gate, reasonCode: row.reasonCode, count: row.count, diagnostic: row.reasonCode === "theory_gate_absent" }));
      const input = survivors + removals.filter((row) => !row.diagnostic).reduce((sum, row) => sum + row.count, 0);
      return { stage, input, survivors, removals, breakdown };
    });
  return { instrumented: true, runId: resolvedRunId, runKind, computedAt: computedAt.toISOString(), stages, recentRuns };
}

// Batch 3 — "All observations" read model (research lane wide). Returns
// EVERY candidate the latest completed discovery run recorded, from the
// stored run records only: the run's paper-handoff candidate snapshot (one
// row per scanned asset, including names excluded before persistence) joined
// with the run's retained discovery signals and the saved universe-tier
// assignment. Tier is rendered as a priority label only. This read never
// computes a score, never re-runs a gate, and feeds no decision path —
// issuance qualification is untouched and shown separately.
const discoveryObservationsResponse = z.object({
  run: z.object({ id: z.number(), status: z.string(), completedAt: z.string(), summary: z.string() }).nullable(),
  rows: z.array(z.object({
    coinId: z.string(), symbol: z.string(), name: z.string().nullable(),
    direction: z.string().nullable(), context: z.string(),
    tierLabel: z.string(), sourceAsOf: z.string().nullable(),
  })),
  // Additive (migration 0067): per-asset ATH gate records for this run.
  // Empty for runs before the capture existed — never backfilled.
  athGateRecords: z.array(z.object({
    coinId: z.string(), symbol: z.string(), evaluatedAt: z.string(),
    athDistancePct: z.number().nullable(), athValue: z.number().nullable(), athDate: z.string().nullable(),
    athRuleFired: z.boolean(), velocityBypassApplied: z.boolean(),
    disposition: z.enum(["excluded_by_ath_gate", "bypassed_velocity", "passed"]),
  })),
  error: z.string().nullable(),
});
type DiscoveryObservationsResponse = z.infer<typeof discoveryObservationsResponse>;

async function readDiscoveryObservations(ctx: Ctx): Promise<DiscoveryObservationsResponse> {
  const db = ctx.db<typeof schema>();
  const run = (await db.select().from(schema.marketDiscoveryRuns).where(inArray(schema.marketDiscoveryRuns.status, ["complete", "degraded"])).orderBy(desc(schema.marketDiscoveryRuns.id)).limit(1))[0] ?? null;
  if (!run) return { run: null, rows: [], athGateRecords: [], error: null };
  const runView = { id: run.id, status: run.status, completedAt: run.completedAt.toISOString(), summary: run.summary };
  // Additive (migration 0067): this run's per-asset ATH gate records.
  // Read-only evidence; a read failure here must not lose the rows above,
  // so it degrades to an empty list rather than throwing.
  let athGateRecords: DiscoveryObservationsResponse["athGateRecords"] = [];
  try {
    const gateRows = await db.select().from(schema.discoveryAthGateRecords).where(eq(schema.discoveryAthGateRecords.discoveryRunId, run.id)).orderBy(asc(schema.discoveryAthGateRecords.id));
    athGateRecords = gateRows.map((row) => ({ coinId: row.coinId, symbol: row.symbol, evaluatedAt: row.evaluatedAt.toISOString(), athDistancePct: row.athDistancePct, athValue: row.athValue, athDate: row.athDate, athRuleFired: row.athRuleFired, velocityBypassApplied: row.velocityBypassApplied, disposition: row.disposition }));
  } catch { athGateRecords = []; }
  const [signals, tierRows] = await Promise.all([
    db.select().from(schema.discoverySignals).where(eq(schema.discoverySignals.latestRunId, run.id)),
    db.select({ coinId: schema.universeTiers.coinId, tier: schema.universeTiers.tier }).from(schema.universeTiers),
  ]);
  const tierByCoin = new Map(tierRows.map((row) => [row.coinId, row.tier]));
  const signalByCoin = new Map(signals.map((row) => [row.coinId, row]));
  const tierLabel = (coinId: string): string => { const tier = tierByCoin.get(coinId); return tier ? `Priority · ${tier}` : "Priority · no saved tier"; };
  const signalContext = (signal: typeof signals[number]): string => `${signal.setupType} · alignment ${signal.alignment} / 100 · evidence tier ${signal.confidenceTier} · ${signal.passedDimensions}/5 gates${signal.discoveryTier === "tier2" ? " · velocity qualifier — did not pass the T1 doors" : " · entered through the T1 doors"}`;
  const handoff = (await db.select().from(schema.paperHandoffRuns).where(eq(schema.paperHandoffRuns.discoveryRunId, run.id)).limit(1))[0] ?? null;
  const candidates = handoff ? await db.select().from(schema.paperHandoffCandidates).where(eq(schema.paperHandoffCandidates.handoffRunId, handoff.id)).orderBy(asc(schema.paperHandoffCandidates.id)) : [];
  const decorated: Array<{ row: DiscoveryObservationsResponse["rows"][number]; alignment: number | null; recorded: number }> = [];
  const seen = new Set<string>();
  candidates.forEach((cand, index) => {
    seen.add(cand.coinId);
    const signal = signalByCoin.get(cand.coinId) ?? null;
    const evidence = parseStored<Record<string, unknown>>(cand.decisionEvidenceJson, {});
    const evName = typeof evidence.name === "string" ? evidence.name : null;
    const evAsOf = typeof evidence.sourceAsOf === "string" ? evidence.sourceAsOf : null;
    const ledger = parseStored<Array<{ status?: unknown }>>(cand.factorLedgerJson, []);
    const ledgerPass = ledger.filter((dim) => dim?.status === "pass").length;
    // Read-derivation only (stored cand.reason untouched): the retired
    // interval-coverage legacy sentence is stripped from the displayed
    // provenance via displayHandoffReason; all other reasons pass through.
    const context = signal ? signalContext(signal) : `${cand.outcome} at ${cand.stage.replace(/_/g, " ")} — ${displayHandoffReason(cand.reason)}${ledger.length ? ` · stored factor ledger ${ledgerPass}/${ledger.length} dimensions pass` : ""}`;
    decorated.push({
      row: { coinId: cand.coinId, symbol: cand.symbol, name: signal?.name ?? evName, direction: cand.direction === "unknown" ? null : cand.direction, context, tierLabel: tierLabel(cand.coinId), sourceAsOf: signal?.sourceAsOf?.toISOString() ?? evAsOf ?? run.completedAt.toISOString() },
      alignment: signal?.alignment ?? null, recorded: index,
    });
  });
  for (const signal of signals) {
    if (seen.has(signal.coinId)) continue;
    decorated.push({
      row: { coinId: signal.coinId, symbol: signal.symbol, name: signal.name, direction: signal.direction, context: signalContext(signal), tierLabel: tierLabel(signal.coinId), sourceAsOf: signal.sourceAsOf?.toISOString() ?? run.completedAt.toISOString() },
      alignment: signal.alignment, recorded: Number.MAX_SAFE_INTEGER,
    });
  }
  decorated.sort((a, b) => (b.alignment ?? -1) - (a.alignment ?? -1) || a.recorded - b.recorded);
  return { run: runView, rows: decorated.map((entry) => entry.row), athGateRecords, error: null };
}

