        const closed = recentFills.filter((fill: any) => fill.closedPnl !== null && fill.closedPnl !== 0); const wins = closed.filter((fill: any) => (fill.closedPnl ?? 0) > 0).length; const cutoff48h = Date.now() - 48 * 3600000; const recent48h = recentFills.filter((fill: any) => (fill.time ?? 0) >= cutoff48h); const buyNotional = recent48h.filter((fill: any) => fill.side === "buy").reduce((sum: number, fill: any) => sum + (fill.price ?? 0) * (fill.size ?? 0), 0); const sellNotional = recent48h.filter((fill: any) => fill.side === "sell").reduce((sum: number, fill: any) => sum + (fill.price ?? 0) * (fill.size ?? 0), 0);
